"""Auth module fixture: definitions + callers for SymbolIndex tests."""
import hashlib


def hash_password(password: str, salt: str) -> str:
    return hashlib.sha256((salt + password).encode()).hexdigest()


def verify_password(password: str, salt: str, expected: str) -> bool:
    return hash_password(password, salt) == expected


class AuthService:
    def __init__(self, salt: str = "pepper"):
        self.salt = salt

    def login(self, user: str, password: str, stored_hash: str) -> bool:
        return verify_password(password, self.salt, stored_hash)

"""Database fixture module — imports auth to create a cross-file edge."""
from src.auth import hash_password

USERS = {}


def create_user(name: str, password: str) -> None:
    USERS[name] = hash_password(password, salt="pepper")


def get_user(name: str):
    return USERS.get(name)

// Utility helpers used by app.js (call-site fixture for symbol tests).
export function formatPrice(amount) {
  return '$' + amount.toFixed(2);
}

export function applyDiscount(amount, percent) {
  return amount * (1 - percent / 100);
}

